21	 * address), so every member of a household derives the same value and it stays stable as new members
22	 * join. Any pre-existing household member that has no identifier yet is back-filled with the same
23	 * value so the whole household shares it. Runs after {@link BuildOwner} (so the entity exists) and
24	 * before {@link SaveOwner}, mutating the not-yet-persisted owner in place.
25	 */
26	public class AssignHouseholdId {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
29	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	        String lastName = normalize(owner.getLastName());
33	        String address = AddressNormalizer.normalize(owner.getAddress());
34	
35	        List<Owner> household = new ArrayList<>();
36	        String existingId = null;
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
39	                continue;
40	            }
41	            if (lastName.equals(normalize(existing.getLastName()))
42	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
43	                household.add(existing);
44	                if (existingId == null && existing.getHouseholdId() != null
45	                        && !existing.getHouseholdId().isBlank()) {
46	                    existingId = existing.getHouseholdId();
47	                }
48	            }
49	        }
50	
51	        String householdId = existingId != null ? existingId : stableId(lastName, address);
52	        owner.setHouseholdId(householdId);
53	        for (Owner member : household) {
54	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
55	                member.setHouseholdId(householdId);
56	                ownerRepository.save(member);
57	            }
58	        }
59	    }
60	
61	    /** Trim, collapse internal whitespace to a single space and lower-case for comparison. */
62	    private static String normalize(String value) {
63	        if (value == null) {
64	            return "";
65	        }
66	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
67	    }
68	
69	    /** First 12 upper-case hex characters of SHA-256 over the normalized last name and address. */
70	    private static String stableId(String lastName, String address) {
71	        try {
72	            byte[] digest = MessageDigest.getInstance("SHA-256")
73	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
74	            StringBuilder sb = new StringBuilder(digest.length * 2);
75	            for (byte b : digest) {
76	                sb.append(String.format("%02x", b));
77	            }
78	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
79	        }
80	        catch (NoSuchAlgorithmException ex) {
81	            throw new IllegalStateException("SHA-256 not available", ex);
82	        }
83	    }
84	}
