14	 * membership immediately after this create.
15	 *
16	 * <p>Runs after {@link AssignHouseholdId} (so the {@code householdId} is set and any pre-existing
17	 * members are back-filled) and before {@link SaveOwner}, mutating the not-yet-persisted owner in
18	 * place.
19	 */
20	public class AssignHouseholdSize {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String householdId = owner.getHouseholdId();
24	        if (householdId == null || householdId.isBlank()) {
25	            owner.setHouseholdSize(1);
26	            return;
27	        }
28	        int count = 1; // the owner being created
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
31	                continue;
32	            }
33	            if (householdId.equals(existing.getHouseholdId())) {
34	                count++;
35	            }
36	        }
37	        owner.setHouseholdSize(count);
38	    }
39	}
