3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a soft (non-hard) duplicate. The new owner is created regardless, but when it is not an exact
9	 * identity match yet shares an existing owner's last name and postcode while having a different
10	 * telephone, it is recorded as a possible duplicate of that owner.
11	 *
12	 * <p>Sets {@code possibleDuplicate} true and {@code possibleDuplicateOf} to the matching owner's id
13	 * (the lowest-id match when several qualify, so the value is deterministic); otherwise
14	 * {@code possibleDuplicate} is set false and {@code possibleDuplicateOf} left null. Hard duplicates —
15	 * an exact identity-key match — never reach here: they are rejected earlier by
16	 * {@link EnsureOwnerIdentityUnique}, and sharing the last name and postcode but with a <em>different</em>
17	 * telephone yields a different identity key, so this is always a create-and-flag, never a reject.
18	 *
19	 * <p>Runs after {@link NormalizeOwnerTelephone} (so telephones compare in canonical form) and after
20	 * {@link BuildOwner} (so the entity, its last name and postcode exist), and before {@link SaveOwner}
21	 * so the flag is persisted with the new row and read back by {@code GET /api/owners/{id}}.
22	 */
23	public class AssignPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String lastName = owner.getLastName();
27	        String postcode = owner.getPostcode();
28	        String telephone = owner.getTelephone();
29	
30	        Integer matchId = null;
31	        if (postcode != null && !postcode.isBlank()) {
32	            for (Owner existing : ownerRepository.findAll()) {
33	                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
34	                    continue;
35	                }
36	                if (equalsIgnoreCase(lastName, existing.getLastName())
37	                        && postcode.equals(existing.getPostcode())
38	                        && !equals(telephone, existing.getTelephone())) {
39	                    if (matchId == null || existing.getId() < matchId) {
40	                        matchId = existing.getId();
41	                    }
42	                }
43	            }
44	        }
45	
46	        owner.setPossibleDuplicate(matchId != null);
47	        owner.setPossibleDuplicateOf(matchId);
48	    }
49	
50	    private static boolean equalsIgnoreCase(String a, String b) {
51	        return a == null ? b == null : a.equalsIgnoreCase(b);
52	    }
53	
54	    private static boolean equals(String a, String b) {
55	        return a == null ? b == null : a.equals(b);
56	    }
57	}
