3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects creating an owner whose derived {@code identityKey} exactly matches an existing owner's.
10	 *
11	 * <p>The key — {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} — is the one
12	 * place duplicate detection now lives, replacing the former separate telephone, email and household
13	 * checks. Because the telephone is part of the key, two members of the same household (same
14	 * {@code householdId}) with different telephones have different keys and are both allowed; only an
15	 * exact full-key match is a duplicate.
16	 *
17	 * <p>Runs after {@link NormalizeOwnerTelephone}/{@link NormalizeOwnerEmail} (so the key uses
18	 * canonical values) and after {@link AssignHouseholdId} (so the {@code householdId} component is
19	 * populated), and before {@link SaveOwner} so a duplicate is a 409 (Conflict) rather than a
20	 * persisted row.
21	 */
22	public class EnsureOwnerIdentityUnique {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        String identityKey = owner.getIdentityKey();
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
29	                continue;
30	            }
31	            if (identityKey.equals(existing.getIdentityKey())) {
32	                throw new DuplicateIdentityException(identityKey);
33	            }
34	        }
35	    }
36	}
